async function scanApkFile(input){
 const file=input?.files?.[0];if(!file)return;const status=document.getElementById('apkScanResult');if(status)status.innerHTML='<div class="status-note">Выполняется локальная проверка APK…</div>';
 const findings=[];let level='low',entries=[],hash='';
 try{
  if(file.size>120*1024*1024)throw new Error('Файл больше 120 МБ. Используйте меньший файл или системный сканер Android.');
  const buf=await file.arrayBuffer(),u=new Uint8Array(buf),dv=new DataView(buf);
  try{if(crypto?.subtle){const h=await crypto.subtle.digest('SHA-256',buf);hash=[...new Uint8Array(h)].map(b=>b.toString(16).padStart(2,'0')).join('')}}catch(_){ }
  let eocd=-1;for(let i=u.length-22;i>=Math.max(0,u.length-65557);i--){if(dv.getUint32(i,true)===0x06054b50){eocd=i;break}}
  if(eocd<0)throw new Error('Не найдена ZIP-структура. Файл может быть повреждён или не является APK.');
  const count=dv.getUint16(eocd+10,true),cdOffset=dv.getUint32(eocd+16,true);let off=cdOffset;
  for(let i=0;i<count&&i<20000&&off+46<u.length;i++){
   if(dv.getUint32(off,true)!==0x02014b50)break;
   const method=dv.getUint16(off+10,true),csize=dv.getUint32(off+20,true),usize=dv.getUint32(off+24,true),nl=dv.getUint16(off+28,true),el=dv.getUint16(off+30,true),cl=dv.getUint16(off+32,true),local=dv.getUint32(off+42,true);
   if(off+46+nl>u.length)break;const name=new TextDecoder().decode(u.slice(off+46,off+46+nl));entries.push({name,method,csize,usize,local});off+=46+nl+el+cl;
  }
  const names=entries.map(e=>e.name);if(!names.includes('AndroidManifest.xml'))findings.push('В архиве нет AndroidManifest.xml — файл может быть некорректным APK.');
  if(!names.some(n=>/^classes(?:\d+)?\.dex$/i.test(n)))findings.push('Не найден classes.dex — проверьте формат файла.');
  if(names.some(n=>/^assets\/.*\.(dex|jar|apk)$/i.test(n)))findings.push('В assets обнаружен вложенный исполняемый файл (DEX/JAR/APK). Это бывает и в легитимных приложениях.');
  if(names.filter(n=>/^classes(?:\d+)?\.dex$/i.test(n)).length>8)findings.push('В архиве необычно много DEX-файлов; проверьте источник и разработчика.');
  const rules=[['android.permission.REQUEST_INSTALL_PACKAGES','Запрашивается разрешение на установку других пакетов.'],['android.permission.SYSTEM_ALERT_WINDOW','Упоминается разрешение отображать окна поверх других приложений.'],['android.permission.READ_SMS','Упоминается доступ к SMS.'],['android.permission.RECEIVE_SMS','Упоминается получение SMS.'],['android.permission.SEND_SMS','Упоминается отправка SMS.'],['android.permission.READ_CALL_LOG','Упоминается чтение журнала звонков.'],['android.permission.BIND_ACCESSIBILITY_SERVICE','Упоминается служба специальных возможностей.'],['getdeviceid','Найдена строка getDeviceId.'],['dexclassloader','Найдена ссылка на DexClassLoader.'],['runtime.exec','Найдена строка Runtime.exec.'],['su -c','Найдена команда su -c.']];
  const seen=new Set();
  for(const en of entries){if(!(/AndroidManifest\.xml|^classes(?:\d+)?\.dex$/i.test(en.name)))continue;if(en.usize>24*1024*1024)continue;
   let data=null;try{const lo=en.local;if(dv.getUint32(lo,true)!==0x04034b50)continue;const nl=dv.getUint16(lo+26,true),el=dv.getUint16(lo+28,true),start=lo+30+nl+el,end=start+en.csize;if(end>u.length)continue;const payload=u.slice(start,end);if(en.method===0)data=payload;else if(en.method===8&&typeof DecompressionStream==='function'){const stream=new Blob([payload]).stream().pipeThrough(new DecompressionStream('deflate-raw'));data=new Uint8Array(await new Response(stream).arrayBuffer())}}catch(_){ }
   if(!data)continue;const txt=new TextDecoder('latin1').decode(data).toLowerCase();for(const [needle,desc]of rules){if(txt.includes(needle)&&!seen.has(needle)){seen.add(needle);findings.push(desc)}}
  }
  if(!names.includes('AndroidManifest.xml')||!names.some(n=>/^classes(?:\d+)?\.dex$/i.test(n)))findings.push('Не все основные элементы APK распознаны; результат может быть неполным.');
  if(findings.length>=3)level='high';else if(findings.length>0)level='review';
  apkScanState={name:file.name,sizeLabel:(file.size/1024/1024).toFixed(2)+' МБ',sha256:hash,level,findings,scope:'Браузерная эвристика: проверены ZIP-структура и только доступные несжатые/распакованные строки. Это не полноценная проверка на вредоносный код и не сертификат безопасности.',entries:entries.length};
 }catch(err){apkScanState={name:file.name,sizeLabel:(file.size/1024/1024).toFixed(2)+' МБ',sha256:hash,level:'high',findings:[err.message||'Не удалось прочитать APK'],scope:'Проверка не завершена; не устанавливайте файл, пока не проверите источник.'}}
 if(status)status.innerHTML=renderApkScanPanel();input.value='';
}

function post(quiet){const a=$('#app');if(!quiet)[...a.children].forEach((e,i)=>e.style.animationDelay=i*60+'ms');requestAnimationFrame(()=>requestAnimationFrame(()=>{
 a.querySelectorAll('.rf').forEach(e=>e.style.strokeDashoffset=326.7*(1-e.dataset.s/100));a.querySelectorAll('.tr i').forEach(e=>e.style.width=e.dataset.w+'%');
 a.querySelectorAll('[data-n]').forEach(e=>{const n=+e.dataset.n,t0=performance.now();(function f(t1){const k=Math.min(1,(t1-t0)/1000);e.textContent=Math.round(n*(1-Math.pow(1-k,3)));if(k<1)requestAnimationFrame(f)})(t0)})}))}

let cyberNewsCache=[];
function safeText(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function localCyberAnalysis(input){
 const x=String(input||'').slice(0,6000), low=x.toLowerCase(), findings=[];
 const rules=[
  [/(\b| )(otp|cvv|cvc|pin|парол[а-я]*|код из sms|одноразов[а-я]* код|sms код)(\b| )/i,'Запрашиваются секретные коды или платёжные данные'],
  [/(срочно|немедленно|zudlik bilan|darhol|urgent|last chance|последний шанс)/i,'Давление срочностью — частый приём социальной инженерии'],
  [/(переведите|переведи|оплатите|инвестируй|гарантированн[а-я]* доход|гарантирован[а-я]* прибыль|выиграли|победител[ья])/i,'Есть финансовое обещание или просьба о переводе денег'],
  [/(https?:\/\/|www\.|t\.me\/|bit\.ly|tinyurl|\.apk\b)/i,'Есть ссылка, сокращатель или упоминание APK — не открывайте до проверки'],
  [/(банк|карта|милици|полици|налогов|доставка|посылк|аккаунт заблокирован)/i,'Сообщение использует имя организации или угрозу блокировки — проверьте через официальный канал']
 ];
 for(const [r,msg] of rules) if(r.test(low)) findings.push(msg);
 const level=findings.length>=3?'Высокий':findings.length===2?'Средний':findings.length===1?'Средний':'Неопределённый';
 return {mode:'local',risk:level,summary:findings.length?'Найдены признаки, требующие проверки. Это эвристика, не доказательство мошенничества.':'Локальные правила не нашли явных признаков. Это НЕ означает, что сообщение безопасно.',findings,actions:['Не сообщайте PIN, CVV, пароль и одноразовые коды.','Не переходите по ссылке из сообщения; самостоятельно откройте официальный сайт или приложение.','Перепроверьте просьбу по независимому каналу.'],disclaimer:'Офлайн-эвристика ограничена и может ошибаться.'};
}
function togglePwVisibility(show){const e=document.getElementById('pwInput');if(e)e.type=show?'text':'password';}
function scorePassword(){const e=document.getElementById('pwInput'),g=document.getElementById('pwGauge'),l=document.getElementById('pwLabel'),a=document.getElementById('pwAdvice');if(!e||!g||!l||!a)return;const p=e.value;if(!p){g.style.width='0';l.textContent='Введите пароль';a.textContent='Используйте длинную уникальную фразу, не повторяйте пароли между сайтами.';return;}let score=0;if(p.length>=12)score+=30;else if(p.length>=8)score+=18;if(/[a-z]/.test(p))score+=12;if(/[A-Z]/.test(p))score+=12;if(/\d/.test(p))score+=12;if(/[^A-Za-z0-9]/.test(p))score+=14;if(p.length>=18)score+=15;if(/(.)\1{2,}/.test(p)||/1234|password|qwerty|admin|letmein/i.test(p))score-=25;score=Math.max(5,Math.min(100,score));g.style.width=score+'%';g.style.background=score<35?'var(--hi)':score<65?'var(--me)':'var(--lo)';l.textContent=score<35?'Слабый пароль':score<65?'Средний пароль':'Хороший по базовым правилам';a.textContent=score<35?'Увеличьте длину и избегайте очевидных слов, повторов и последовательностей.':score<65?'Сделайте пароль длиннее и более уникальным; не используйте личные сведения.':'Хорошая основа. Используйте его только для одного аккаунта и сохраните в менеджере паролей.';}
function getApiBase(){try{return String(localStorage.getItem('fs_api_base')||'').trim().replace(/\/$/,'')}catch(e){return '';}}
function saveApiBase(){const e=document.getElementById('apiBase');const value=(e?.value||'').trim().replace(/\/$/,'');if(value&&!/^https:\/\//i.test(value)){toast('Укажите HTTPS-адрес сервера');return;}try{localStorage.setItem('fs_api_base',value);toast('Адрес сервера сохранён');}catch(err){toast('Не удалось сохранить адрес');}}

function liveTextPreview(){const el=document.getElementById('liveText'),box=document.getElementById('textLiveStatus');if(!el||!box)return;const value=el.value.trim();if(!value){box.textContent='Текст проверяется локальными правилами. ИИ не используется.';return;}const r=localCyberAnalysis(value);box.textContent=r.findings.length?`⚠️ Найдено признаков риска: ${r.findings.length}. Это предварительная эвристика.`:'Явных признаков по локальным правилам не найдено; это не гарантирует безопасность.';}
function liveProtectionInput(){liveTextPreview();}
function clearLiveCheck(){const u=document.getElementById('liveUrl'),r=document.getElementById('urlCheckResult'),s=document.getElementById('urlCheckStatus');if(u)u.value='';if(r)r.innerHTML='';if(s)s.textContent='Вставьте ссылку для проверки.';}
async function checkLiveUrl(){const input=document.getElementById('liveUrl'),status=document.getElementById('urlCheckStatus'),box=document.getElementById('urlCheckResult');if(!input||!input.value.trim()){toast('Вставьте ссылку');return;}const raw=input.value.trim();let u;try{u=new URL(/^https?:\/\//i.test(raw)?raw:'https://'+raw)}catch(e){status.textContent='Не удалось распознать ссылку. Проверьте адрес.';return;}const host=u.hostname.toLowerCase(),findings=[];if(u.protocol!=='https:')findings.push('Используется HTTP без шифрования');if(/^\d{1,3}(\.\d{1,3}){3}$/.test(host))findings.push('В адресе используется IP вместо обычного домена');if(host.includes('xn--'))findings.push('Домен содержит Punycode — проверьте похожие символы');if(host.split('.').length>4)findings.push('Необычно много поддоменов');if(/bit\.ly|tinyurl|t\.co|goo\.gl|cutt\.ly|rb\.gy/i.test(host))findings.push('Обнаружен сокращённый URL — конечный адрес скрыт');if(/login|verify|secure|bank|wallet|bonus|gift|prize|pay|account|support/i.test(host))findings.push('В домене есть слова, часто используемые в приманках; это не доказательство мошенничества');if(u.username||u.password)findings.push('Адрес содержит данные перед символом @ — возможная маскировка домена');const score=Math.min(95,findings.length*18+(u.protocol==='http:'?10:0));const risk=score>=55?'Высокий':score>=25?'Средний':'Неопределённый';status.textContent='Проверка выполнена полностью на устройстве. Внешняя база угроз не используется.';box.innerHTML=`<div class="card"><h2 style="color:${risk==='Высокий'?'#b91c1c':risk==='Средний'?'#b45309':'var(--tx)'}">Предварительный риск: ${risk} (${score}/100)</h2><p><b>Домен:</b> ${safeText(host)}</p>${findings.map(x=>`<p>⚠️ ${safeText(x)}</p>`).join('')||'<p>Локальные правила не нашли явных подозрительных признаков.</p>'}<p><b>Совет:</b> ${findings.length?'Не открывайте ссылку, пока не подтвердите отправителя и настоящий домен.':'Даже отсутствие признаков не доказывает безопасность сайта.'}</p><div class="row"><button class="btn" onclick="copyCheckedUrl()">📋 Копировать адрес</button><button class="btn" onclick="clearLiveCheck()">Очистить</button></div><p class="mu">Офлайн-эвристика не сверяет адрес с актуальными чёрными списками и может ошибаться.</p></div>`;window.fsCheckedUrl=u.href;} 
function copyCheckedUrl(){if(window.fsCheckedUrl)cp(window.fsCheckedUrl)}
function checkLiveText(){const input=document.getElementById('liveText'),box=document.getElementById('textCheckResult');if(!input||!input.value.trim()){toast('Вставьте текст');return;}const d=localCyberAnalysis(input.value.trim());box.innerHTML=`<div class="card"><h2>Предварительный риск: ${safeText(d.risk)}</h2><p>${safeText(d.summary)}</p>${d.findings.map(x=>`<p>⚠️ ${safeText(x)}</p>`).join('')||'<p>Явных признаков по локальным правилам не найдено.</p>'}<h3>Что делать</h3>${d.actions.map(x=>`<p>✓ ${safeText(x)}</p>`).join('')}<p class="mu">Текст остаётся на устройстве: запросы к серверу и ИИ не выполняются. Локальные правила могут ошибаться.</p></div>`;}
async function refreshThreatStatus(){const box=document.getElementById('threatStatus');if(!box)return;box.textContent='Проверяем доступность базы…';try{const r=await fetch(getApiBase()+'/api/threat-status');const d=await r.json();box.textContent=`OpenPhish: ${d.available?'доступна':'недоступна'}; записей URL/доменов в кеше: ${d.count||0}; обновлено: ${d.updatedAt?new Date(d.updatedAt).toLocaleString():'нет данных'}.${d.error?' '+d.error:''}`;}catch(e){box.textContent='Не удалось получить статус: '+e.message;}}
function openCheckedUrl(){const input=document.getElementById('liveUrl');if(!input||!input.value.trim())return;const url=input.value.trim();try{if(window.FiribStopNative&&window.FiribStopNative.openExternalUrl){window.FiribStopNative.openExternalUrl(url)}else{if(confirm('FiribStop не может гарантировать безопасность. Открыть ссылку в браузере?'))window.open(url,'_blank','noopener,noreferrer')}}catch(e){toast('Не удалось открыть ссылку');}}
function onNativeNavigationUrl(raw){let url=String(raw||'').trim();if(!url)return;go('ai');setTimeout(()=>{const input=document.getElementById('liveUrl');if(input){input.value=url;checkLiveUrl();}},180);}
function onNativeSharedContent(raw){let d;try{d=typeof raw==='string'?JSON.parse(raw):raw}catch(e){d={text:String(raw||'')}};const value=String(d.url||d.text||'').trim();if(!value)return;go('ai');setTimeout(()=>{const urls=value.match(/https?:\/\/[^\s<>"']+|(?:www\.)[a-z0-9.-]+\.[a-z]{2,}(?:\/[^\s<>"']*)?/i);if(urls){const el=document.getElementById('liveUrl');if(el)el.value=urls[0].replace(/[),.!?]+$/,'');checkLiveUrl();}const tx=document.getElementById('liveText');if(tx&&!urls){tx.value=value;liveTextPreview();checkLiveText();}else if(tx){tx.value=value;liveTextPreview();}},180);}
function saveOfflineCacheNow(){try{sv('fs_offline_news',{items:cyberNewsCache.slice(0,100),updatedAt:new Date().toISOString()});toast('Лента сохранена для офлайн-доступа');if(view==='offline')render()}catch(e){toast('Не удалось сохранить данные')}}
function checkOfflineStatus(){const el=document.getElementById('offlineStatus');if(!el)return;el.textContent=`Сеть: ${navigator.onLine?'подключена':'нет подключения'} · Service Worker: ${('serviceWorker' in navigator)?'поддерживается':'не поддерживается'} · Локальные проверки доступны`;}
window.addEventListener('online',()=>{if(view==='offline')render(true)});window.addEventListener('offline',()=>{if(view==='offline')render(true)});
async function loadCyberNews(force){
 const status=document.getElementById('newsStatus');if(!status)return;
 status.textContent='Загружаем публикации…';
 try{const r=await fetch(getApiBase()+'/api/news'+(force?'?refresh=1':''),{headers:{Accept:'application/json'}});const d=await r.json();if(!r.ok)throw new Error(d.error||'Ошибка загрузки');cyberNewsCache=d.items||[];try{sv('fs_offline_news',{items:cyberNewsCache.slice(0,100),updatedAt:d.updatedAt||new Date().toISOString()})}catch(e){}notifyImportantNews(cyberNewsCache);const okSources=(d.sources||[]).filter(x=>x.ok).length,failedSources=(d.sources||[]).filter(x=>!x.ok).length;status.textContent=`Публикаций: ${cyberNewsCache.length}. Источники доступны: ${okSources}; с ошибками: ${failedSources}. Обновлено: ${d.updatedAt?new Date(d.updatedAt).toLocaleString():'неизвестно'}.`;filterCyberNews()}
 catch(e){const cached=ld('fs_offline_news',{});cyberNewsCache=Array.isArray(cached.items)?cached.items:[];status.textContent=cyberNewsCache.length?`Сеть недоступна. Показаны сохранённые публикации (${cyberNewsCache.length}); сохранено: ${cached.updatedAt?new Date(cached.updatedAt).toLocaleString('ru-RU'):'дата неизвестна'}.`:'Лента сейчас недоступна. Подключитесь к интернету, чтобы загрузить новости. Ошибка: '+e.message;filterCyberNews()}
}
function formatCyberNewsDate(value){if(!value)return 'Дата не указана';const d=new Date(value);return Number.isNaN(d.getTime())?'Дата не указана':d.toLocaleDateString();}
function filterCyberNews(){
 const box=document.getElementById('newsList');if(!box)return;const q=(document.getElementById('newsSearch')?.value||'').toLowerCase(), important=document.getElementById('newsImportant')?.checked;
 const items=cyberNewsCache.filter(n=>(!important||n.important)&&(`${n.title} ${n.description} ${n.category} ${n.source}`).toLowerCase().includes(q));
 box.innerHTML=items.length?items.map(n=>`<article class="card"><div class="mu">${safeText(n.source)} · ${safeText(formatCyberNewsDate(n.date))} ${n.important?'· 🔴 Важное предупреждение':''}</div><h3>${safeText(n.title)}</h3><p>${safeText(n.description||'Описание не предоставлено источником.')}</p><p class="mu">Категория: ${safeText(n.category||'Общее')}</p><a class="news-source-link" href="${safeText(n.url)}" target="_blank" rel="noopener noreferrer">Первоисточник ↗</a></article>`).join(''):'<div class="status-note">Нет публикаций по выбранному фильтру. Попробуйте изменить запрос или откройте официальные сайты ниже.</div>';
}

function toggleNewsNotifications(enabled){
 try{localStorage.setItem('fs_news_notify',enabled?'1':'0')}catch(e){}
 if(!enabled){toast('Уведомления отключены');return}
 if(!('Notification' in window)){toast('Этот браузер не поддерживает уведомления');return}
 Notification.requestPermission().then(p=>{if(p==='granted')toast('Уведомления включены, пока приложение открыто');else{const cb=document.getElementById('newsNotify');if(cb)cb.checked=false;toast('Разрешение на уведомления не выдано')}}).catch(()=>toast('Не удалось запросить разрешение'));
}
function notifyImportantNews(items){
 let enabled=false;try{enabled=localStorage.getItem('fs_news_notify')==='1'}catch(e){}
 if(!enabled||!('Notification' in window)||Notification.permission!=='granted')return;
 let seen=[];try{seen=JSON.parse(localStorage.getItem('fs_news_seen')||'[]')}catch(e){}
 const current=items.filter(n=>n.important&&!seen.includes(n.id));
 current.slice(0,3).forEach(n=>{try{const note=new Notification('FiribStop: важное предупреждение',{body:n.title,tag:'firibstop-'+n.id});note.onclick=()=>{window.focus();window.open(n.url,'_blank','noopener');note.close()}}catch(e){}});
 try{localStorage.setItem('fs_news_seen',JSON.stringify([...seen,...current.map(n=>n.id)].slice(-300)))}catch(e){}
}
async function renderThreatAnalytics(force=false){const box=document.getElementById('threatAnalytics');if(!box)return;try{const r=await fetch(getApiBase()+'/api/analytics'+(force?'?refresh=1':''),{headers:{Accept:'application/json'}});const d=await r.json();if(!r.ok)throw new Error(d.error||'API недоступен');const cats=Object.entries(d.categories||{}).sort((a,b)=>b[1]-a[1]);const sources=Object.entries(d.sources||{}).sort((a,b)=>b[1]-a[1]).slice(0,5);const months=Object.entries(d.months||{}).sort((a,b)=>a[0].localeCompare(b[0])).slice(-6);box.innerHTML=`<div class="card"><b>Всего публикаций</b><div style="font-size:30px;font-weight:800">${Number(d.total)||0}</div></div><div class="card"><b>Важные публикации</b><div style="font-size:30px;font-weight:800;color:#dc2626">${Number(d.important)||0}</div></div><div class="card"><b>Категории</b>${cats.length?cats.map(([k,v])=>`<div class="region-row"><span>${safeText(k)}</span><b>${v}</b></div>`).join(''):'<p class="mu">Нет данных</p>'}</div><div class="card"><b>Источники</b>${sources.length?sources.map(([k,v])=>`<div class="region-row"><span>${safeText(k)}</span><b>${v}</b></div>`).join(''):'<p class="mu">Нет данных</p>'}</div><div class="card"><b>Публикации по месяцам</b>${months.length?months.map(([k,v])=>`<div class="region-row"><span>${safeText(k)}</span><b>${v}</b></div>`).join(''):'<p class="mu">Нет дат</p>'}</div><p class="mu">Обновлено: ${d.updatedAt?safeText(new Date(d.updatedAt).toLocaleString('ru-RU')):'нет данных'}. ${safeText(d.method||'')}</p>`;}catch(e){box.innerHTML=`<p class="status-note">Аналитика не загружена: ${safeText(e.message)}. Проверьте сервер и обновите источники.</p>`;}}
const threatRegionAliases=[
 {name:'Республика Каракалпакстан',keys:['каракалпакстан','karakalpakstan','nukus']},
 {name:'Андижанская область',keys:['андижан','andijan','andijon']},
 {name:'Бухарская область',keys:['бухар','bukhara','buxoro']},
 {name:'Джизакская область',keys:['джизак','jizzakh','jizzax']},
 {name:'Кашкадарьинская область',keys:['кашкадар','kashkadarya','qarshi']},
 {name:'Навоийская область',keys:['навоий','navoi','navoiy']},
 {name:'Наманганская область',keys:['наманган','namangan']},
 {name:'Самаркандская область',keys:['самарканд','samarkand','samarqand']},
 {name:'Сурхандарьинская область',keys:['сурхандар','surkhandarya','термез','termiz']},
 {name:'Сырдарьинская область',keys:['сырдар','syrdarya','gulistan','guliston']},
 {name:'Ташкентская область',keys:['ташкентская область','tashkent region','toshkent viloyati']},
 {name:'Ферганская область',keys:['ферган','ferghana','fargona']},
 {name:'Хорезмская область',keys:['хорезм','khorezm','urgench','urganch']},
 {name:'город Ташкент',keys:['город ташкент','г. ташкент','tashkent city','toshkent shahri']}
];
let threatLeafletMap=null,threatGeoLayer=null,threatGeoData=null,threatMapLoadPromise=null;
const THREAT_GEO_CACHE='fs_uzbekistan_regions_geojson_v1';
function normalizeRegionText(v){return String(v||'').toLocaleLowerCase('ru-RU').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[’‘`]/g,"'").replace(/[^a-zа-я0-9]+/g,' ').trim();}
function threatItemsForRegion(region){const keys=region.keys.map(normalizeRegionText);return cyberNewsCache.filter(n=>{const t=normalizeRegionText(String(n.title||'')+' '+String(n.description||''));return keys.some(k=>k.length>3&&(` ${t} `).includes(` ${k} `));});}
function regionFromFeature(feature){const p=feature?.properties||{};const candidates=[p.name_ru,p.name,p.NAME_1,p.shapeName,p.NAME_2,p.admin1Name,p.region].filter(Boolean).map(normalizeRegionText);return threatRegionAliases.find(r=>{const keys=[r.name,...r.keys].map(normalizeRegionText);return candidates.some(raw=>keys.some(k=>raw===k||raw.includes(k)||k.includes(raw)));})||null;}
function threatMentionCount(region){return region?threatItemsForRegion(region).length:0;}
function threatStyle(feature){const region=regionFromFeature(feature),count=threatMentionCount(region),root=document.documentElement,dark=root.dataset.theme==='dark'||(!root.dataset.theme&&matchMedia('(prefers-color-scheme: dark)').matches);const max=Math.max(1,...threatRegionAliases.map(threatMentionCount));const ratio=count/max;const fill=count===0?(dark?'#19334a':'#dff4f0'):ratio>.75?'#ff1744':ratio>.45?'#ff3d5a':ratio>.2?'#e05252':'#9b394d';return {color:count?'#ff647c':(dark?'#39d9f2':'#168b83'),weight:count?1.8:1.3,opacity:1,fillColor:fill,fillOpacity:count?Math.min(.78,.36+ratio*.4):(dark?.24:.55)};}
function showThreatRegion(region){if(!region)return;const matches=threatItemsForRegion(region),title=document.getElementById('threatRegionTitle'),summary=document.getElementById('threatRegionSummary'),items=document.getElementById('threatRegionItems');if(!title||!summary||!items)return;title.textContent=region.name;summary.textContent=matches.length?`В сохранённой ленте найдено упоминаний региона: ${matches.length}. Это совпадения по тексту, а не подтверждённые инциденты. Последняя дата публикации: ${safeText(formatCyberNewsDate(matches.map(n=>n.date).filter(Boolean).sort().pop()))}.`:'В текущей сохранённой ленте нет явных упоминаний региона. Это не означает, что угроз нет.';items.innerHTML=matches.length?matches.map(n=>`<article class="card" style="padding:12px"><div class="mu">${safeText(n.source||'Источник не указан')} · ${safeText(formatCyberNewsDate(n.date))}</div><b>${safeText(n.title||'Публикация')}</b><p>${safeText(n.description||'Описание не предоставлено источником.')}</p><a href="${safeText(/^https:\/\//i.test(n.url||'')?n.url:'https://uzcert.uz/') }" target="_blank" rel="noopener noreferrer">Открыть первоисточник ↗</a></article>`).join(''):'<p class="muted">Нет публикаций с явным упоминанием региона в сохранённой ленте. Проверьте официальные источники отдельно.</p>';document.querySelectorAll('[data-region-name]').forEach(b=>b.classList.toggle('selected',b.dataset.regionName===region.name));}
function renderThreatRegionList(){const list=document.getElementById('threatRegionList');if(!list)return;list.innerHTML=threatRegionAliases.map((r,i)=>`<button type="button" class="region-chip" data-region-name="${safeText(r.name)}" onclick="showThreatRegion(threatRegionAliases[${i}]);if(threatGeoLayer){threatGeoLayer.eachLayer(l=>{if(regionFromFeature(l.feature)?.name==='${r.name.replace(/'/g,"\'")}')threatLeafletMap.fitBounds(l.getBounds(),{padding:[18,18],maxZoom:8})})}">${safeText(r.name)}</button>`).join('');}
function resetThreatMap(){if(threatLeafletMap&&threatGeoLayer)threatLeafletMap.fitBounds(threatGeoLayer.getBounds(),{padding:[8,8]});const t=document.getElementById('threatRegionTitle');if(t)t.textContent='Выберите регион';const s=document.getElementById('threatRegionSummary');if(s)s.textContent='Нажмите на регион карты или выберите его в списке.';const i=document.getElementById('threatRegionItems');if(i)i.innerHTML='<p class="muted">Выберите регион, чтобы увидеть совпадения по сохранённым публикациям.</p>';document.querySelectorAll('[data-region-name]').forEach(b=>b.classList.remove('selected'));}
async function fetchRegionGeoJSON(){try{const cached=localStorage.getItem(THREAT_GEO_CACHE);if(cached){const j=JSON.parse(cached);if(j&&Array.isArray(j.features)&&j.features.length)return {data:j,cached:true};}}catch(e){}const urls=[getApiBase()+'/api/regions','https://raw.githubusercontent.com/akbartus/GeoJSON-Uzbekistan/main/geojson/uzbekistan_regional.geojson','https://raw.githubusercontent.com/negeloT/uzbekistan_borders/main/GEOJSON_LVL/uzbekistan_lvl2.geojson'];for(const url of urls){try{const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),10000);const r=await fetch(url,{signal:controller.signal,cache:'no-cache'});clearTimeout(timer);if(!r.ok)continue;const j=await r.json();if(j&&Array.isArray(j.features)&&j.features.length>=10){try{const packed=JSON.stringify(j);if(packed.length<3500000)localStorage.setItem(THREAT_GEO_CACHE,packed);}catch(e){}return {data:j,cached:false};}}catch(e){}}return null;}
function renderMapNewsFeed(){const box=document.getElementById('threatRegionItems');if(!box)return;const selected=document.getElementById('threatRegionTitle')?.textContent||'';if(threatRegionAliases.some(r=>r.name===selected))return;const items=cyberNewsCache.slice().sort((a,b)=>Date.parse(b.date||0)-Date.parse(a.date||0)).slice(0,8);box.innerHTML=`<div class="map-feed-title"><b>Последние публикации</b><span class="local-pill">${items.length} шт.</span></div><p class="muted">Лента из RSS-источников. Красный цвет региона отражает только текстовые упоминания, а не подтверждённое число атак.</p>`+(items.length?items.map(n=>`<article class="map-feed-item"><div class="mu">${safeText(n.source||'Источник')} · ${safeText(formatCyberNewsDate(n.date))}${n.important?' · 🔴 Важное':''}</div><b class="map-feed-headline">${safeText(n.title||'Публикация')}</b><div><a class="news-source-link" href="${safeText(/^https:\/\//i.test(n.url||'')?n.url:'https://uzcert.uz/')}" target="_blank" rel="noopener noreferrer">Первоисточник ↗</a></div><p>${safeText((n.description||'').slice(0,220))}</p></article>`).join(''):'<p class="muted">Новости не загружены. Настройте адрес API-сервера в разделе «Антивирус (бета)» или подключите интернет и обновите источники.</p>');}
async function refreshMapNews(){try{const r=await fetch(getApiBase()+'/api/news',{headers:{Accept:'application/json'}});if(!r.ok)throw new Error('HTTP '+r.status);const d=await r.json();if(Array.isArray(d.items)){cyberNewsCache=d.items;try{sv('fs_offline_news',{items:cyberNewsCache.slice(0,100),updatedAt:d.updatedAt||new Date().toISOString()})}catch(e){}renderMapNewsFeed();if(threatGeoLayer)threatGeoLayer.setStyle(threatStyle);const status=document.getElementById('mapLoadStatus');if(status){const ok=(d.sources||[]).filter(x=>x.ok).length,failed=(d.sources||[]).filter(x=>!x.ok).length;status.textContent=`Границы и новости загружаются через интернет. RSS-источники доступны: ${ok}; с ошибками: ${failed}. Обновлено: ${d.updatedAt?new Date(d.updatedAt).toLocaleString('ru-RU'):'дата неизвестна'}. Публикации не подтверждают географию атаки.`}}}catch(e){const status=document.getElementById('mapLoadStatus');if(status)status.textContent='Не удалось обновить новостную ленту с сервера. Показаны только сохранённые публикации, если они есть. '+e.message;}}
async function initThreatMap(){const el=document.getElementById('threatMap');if(!el)return;renderThreatRegionList();if(!cyberNewsCache.length){const c=ld('fs_offline_news',{});cyberNewsCache=Array.isArray(c.items)?c.items:[];}const status=document.getElementById('mapLoadStatus'),pill=document.getElementById('mapModePill');if(threatLeafletMap){setTimeout(()=>threatLeafletMap.invalidateSize(),60);return;}if(threatMapLoadPromise)return threatMapLoadPromise;threatMapLoadPromise=(async()=>{const result=await fetchRegionGeoJSON();if(!result){if(pill)pill.textContent='Офлайн-режим';if(status)status.textContent='Не удалось загрузить границы регионов. Список регионов остаётся доступным; карта появится после подключения к интернету и повторного открытия раздела.';el.innerHTML='<div class="map-empty"><b>Геометрия карты пока недоступна.</b><p>Выберите регион в списке справа. Приложение не будет показывать выдуманные границы или данные об атаках.</p></div>';return;}threatGeoData=result.data;if(typeof L==='undefined'){if(pill)pill.textContent='Список регионов';if(status)status.textContent='Библиотека интерактивной карты не загрузилась. Геометрия получена, но карта не может отобразиться. Список регионов доступен ниже.';el.innerHTML='<div class="map-empty">Для интерактивной карты требуется загрузить Leaflet. Вы можете выбрать регион из списка.</div>';return;}el.innerHTML='';threatLeafletMap=L.map(el,{scrollWheelZoom:false,preferCanvas:true}).setView([41.3,64.5],5);threatLeafletMap.setMaxBounds([[36.5,55.5],[46.0,74.5]]);let tiles=null,baseFailoverStarted=false,primaryTileErrors=0;const fallbackAttribution='© OpenStreetMap contributors © CARTO';function addBaseTiles(useFallback){const mapThemeDark=document.documentElement.dataset.theme==='dark'||(!document.documentElement.dataset.theme&&matchMedia('(prefers-color-scheme: dark)').matches);const layer=useFallback?L.tileLayer(mapThemeDark?'https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png':'https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png',{subdomains:'abcd',className:'fs-carto-tile',minZoom:4,maxZoom:20,attribution:fallbackAttribution,keepBuffer:3,updateWhenIdle:true}):L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{minZoom:4,maxZoom:19,attribution:'© <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener noreferrer">OpenStreetMap contributors</a>',keepBuffer:3,updateWhenIdle:true});layer.addTo(threatLeafletMap);layer.on('tileerror',()=>{if(useFallback){if(status)status.textContent='Не удалось загрузить карту. Проверьте подключение к интернету и обновите страницу.';return;}primaryTileErrors++;if(status)status.textContent='Подложка OpenStreetMap загружается с ошибками. Пробуем резервный источник…';if(!baseFailoverStarted) setTimeout(()=>{if(primaryTileErrors>0&&!baseFailoverStarted){baseFailoverStarted=true;try{threatLeafletMap.removeLayer(layer)}catch(e){}tiles=addBaseTiles(true);if(status)status.textContent='Используется резервная картографическая подложка CARTO.'}},1800)});return layer}tiles=addBaseTiles(false);window.fsRefreshMapTheme=()=>{if(baseFailoverStarted&&tiles){try{threatLeafletMap.removeLayer(tiles)}catch(e){}tiles=addBaseTiles(true)}};threatGeoLayer=L.geoJSON(threatGeoData,{style:threatStyle,onEachFeature:(f,layer)=>{const region=regionFromFeature(f),raw=String(f.properties?.name_ru||f.properties?.name||f.properties?.NAME_1||f.properties?.shapeName||'Регион');layer.bindTooltip(region?region.name:raw);layer.on('mouseover',()=>layer.setStyle({weight:2.2,fillOpacity:.58}));layer.on('mouseout',()=>threatGeoLayer.resetStyle(layer));layer.on('click',()=>{if(region)showThreatRegion(region);else{const t=document.getElementById('threatRegionTitle');const s=document.getElementById('threatRegionSummary');if(t)t.textContent=raw;if(s)s.textContent='Не удалось сопоставить название объекта с локальным справочником регионов. Данные об угрозах не выводятся.';}});}}).addTo(threatLeafletMap);threatLeafletMap.fitBounds(threatGeoLayer.getBounds(),{padding:[8,8]});threatLeafletMap.whenReady(()=>setTimeout(()=>threatLeafletMap.invalidateSize({pan:false}),250));window.addEventListener('resize',()=>threatLeafletMap&&threatLeafletMap.invalidateSize({pan:false}));renderMapNewsFeed();threatGeoLayer.setStyle(threatStyle);setTimeout(()=>threatLeafletMap.invalidateSize(),120);if(pill)pill.textContent=result.cached?'Границы из кеша':'Карта загружена';if(status)status.textContent=result.cached?'Границы регионов загружены из кеша этого устройства. Подложка OpenStreetMap требует интернет.':'Границы регионов загружены из открытого GeoJSON-источника и сохранены в локальный кеш. Подложка OpenStreetMap требует интернет.';})().finally(()=>{threatMapLoadPromise=null;});return threatMapLoadPromise;}
const oldGo=go;
go=function(v){oldGo(v);if(v==='ai'){const input=document.getElementById('apiBase');try{if(input)input.value=localStorage.getItem('fs_api_base')||''}catch(e){}refreshThreatStatus()}if(v==='news'){const cb=document.getElementById('newsNotify');try{if(cb)cb.checked=localStorage.getItem('fs_news_notify')==='1'}catch(e){}loadCyberNews(false)}if(v==='threatmap'){if(!cyberNewsCache.length){const c=ld('fs_offline_news',{});cyberNewsCache=Array.isArray(c.items)?c.items:[]}setTimeout(async()=>{await refreshMapNews();await initThreatMap();const el=document.getElementById('threatMap');if(el&&!document.querySelector('.map-disclaimer')){const d=document.createElement('div');d.className='map-disclaimer';d.innerHTML='<b>⚠ Важно</b>Цвет региона показывает только частоту текстовых упоминаний в сохранённой новостной ленте. Это не подтверждённые инциденты и не статистика атак в реальном времени.';el.parentNode.insertBefore(d,el);}},120)}};
setInterval(()=>{if(view==='news')loadCyberNews(false)},10*60*1000);

function selectFsRegion(btn,name){document.querySelectorAll('.region-chip').forEach(x=>x.classList.remove('selected'));btn.classList.add('selected');const t=document.getElementById('fsRegionTitle');if(t)t.textContent=name;}
function render(quiet){document.documentElement.lang=lang;document.documentElement.style.fontSize=big?'19px':'';
 $('.sb').classList.toggle('col',col_);
 $('#nav').innerHTML=NAV.map(([k,e,l])=>`<button class="nv ${view===k||(view==='result'&&k==='check')?'on':''}" onclick="go('${k}')"><span class="e">${e}</span><span class="lb">${t(l)}</span></button>`).join('');
 $('#bg').classList.toggle('on',big);
 $('#app').className=quiet?'':'view';$('#app').innerHTML=V[view]();if(view==='antivirus'){try{FiribStopAV&&FiribStopAV.tryLoadBundledDB()}catch(e){}}post(quiet)}
render();
